from typing import List

def period_exp(lam: List[int]) -> int:
    n = len(lam)
    return sum((2 * i + 1 - n) * lam[i] for i in range(n))

def dual(lam: List[int]) -> List[int]:
    n = len(lam)
    return [-lam[n - 1 - i] for i in range(n)]

def twist(k: int, lam: List[int]) -> List[int]:
    return [x + k for x in lam]

def verify_orbit(lam: List[int], krange: range) -> bool:
    base = period_exp(lam)
    ok = True
    for k in krange:
        val = period_exp(dual(twist(k, lam)))
        print(f'k={k:+d}: dual(twist) -> e={val}')
        ok = ok and (val == base)
    print(f'base e(L)={base}; functional equation holds: {ok}')
    return ok

if __name__ == '__main__':
    verify_orbit([4, 2, -1, -3, -5], range(-6, 7))

